std::optional<Vector> Refract(const Vector& ray, const Vector& normal, double eta) {
    const double projection = DotProduct(normal, ray);
    const double discriminant = 1 - eta * eta * (1 - projection * projection);
    if (discriminant < 0) {
        return std::nullopt;
